def priority(task, state, late_w=1.0, prem=1.0, age=0.2):
    p = max(task.estimated_runtime, 1e-6)
    w = max(task.weight, 0.0)
    slack = task.due - state.now
    if slack > 0.0:
        pri = w * p / max(slack, 1e-6)
    else:
        pri = late_w * w / p * (1.0 + (-slack) / p)
    if task.tenant == 'premium' and slack < p + max(state.mean_est, p):
        pri += prem * w / p
    wait = state.now - task.release
    pri += age * w * wait / (p * p)
    return pri

