import math
def priority(task, state, qth=6.0, util_th=0.7, a=0.4, k=1.0, m=1.5, spt=0.5, backlog_th=2.0):
    p = max(task.estimated_runtime, 1e-6)
    now = state.now
    cr = -(task.due - now) / p
    slack = max(0.0, task.due - p - now)
    mean_est = max(state.mean_est, 1e-6)
    atc = max(task.weight, 1e-6) / p * math.exp(-slack / max(k * mean_est, 1e-6))
    tier = m if task.tenant == 'premium' else 1.0
    backlog = state.queue_work / max(state.capacity * mean_est, 1e-6)
    if state.queue_len > qth or state.free < util_th * state.capacity or backlog > backlog_th:
        return tier * (cr + a * atc + spt / p)
    return cr + tier * (a * atc)

