import math
def priority(task, state, a=1.0, b=0.5, c=1.0, d=0.1):
    est = max(task.estimated_runtime, 1e-6)
    w = max(task.weight, 1e-6)
    slack = task.due - state.now - est
    wait = max(0.0, state.now - task.release)
    if slack >= 0.0:
        return -task.due - a * slack / w + b * wait / est
    else:
        return -task.due + c * w / est * (-slack) + d * w / est * wait

