import math
def priority(task, state, wb=1.0, ab=0.2, pb=0.5):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    wait = max(0.0, now - task.release)
    w = max(task.weight, 1e-6)
    adj_due = task.due - wb * math.log(w) - ab * wait
    if task.tenant == 'premium':
        adj_due -= pb
    return -max(adj_due, now + est)

