def priority(task, state, t=1.0, a=0.8, b=0.15, m=1.5):
    p = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - state.now - p
    score = -task.due
    if slack <= t * mean:
        score += a * task.weight / p
    if slack <= 0.0:
        score += b * task.weight * (-slack) / p
    if task.tenant == 'premium':
        score += m
    return score

