import math
def priority(task, state, k=1.0, late_scale=0.25, cap=50.0):
    r = max(task.estimated_runtime, 1e-6)
    mean = max(state.mean_est, 1e-6)
    slack = task.due - r - state.now
    scale = max(k * mean, 1e-6)
    if slack >= 0.0:
        expo = -slack / scale
    else:
        expo = (-slack) * late_scale / scale
    expo = max(-cap, min(cap, expo))
    return task.weight / r * math.exp(expo)

